<?php

declare(strict_types=1);

use App\Core\Auth;
use App\Core\Csrf;
use App\Core\Env;

define('BASE_PATH',dirname(__DIR__));
spl_autoload_register(static function(string $class):void{if(!str_starts_with($class,'App\\'))return;$file=BASE_PATH.'/app/'.str_replace('\\','/',substr($class,4)).'.php';if(is_file($file))require $file;});
Env::load(BASE_PATH.'/.env');
if(session_status()!==PHP_SESSION_ACTIVE){session_name('veelox_portal');session_set_cookie_params(['httponly'=>true,'secure'=>isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','samesite'=>'Lax','path'=>'/']);session_start();}
if(!Auth::check()){header('Location: /login');exit;}if((Auth::user()['role']??'')!=='admin'){http_response_code(403);exit('Administrator access is required.');}
$envPath=BASE_PATH.'/.env';$errors=[];$saved=false;
function envQuote(string $value):string{return '"'.str_replace(['\\','"'],['\\\\','\\"'],$value).'"';}
function updateEnv(string $source,string $key,string $value):string{$line=$key.'='.envQuote($value);$pattern='/^'.preg_quote($key,'/').'=.*$/m';return preg_match($pattern,$source)?(string)preg_replace($pattern,$line,$source):rtrim($source).PHP_EOL.$line.PHP_EOL;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Csrf::verify($_POST['_token']??null))$errors[]='Your session expired. Refresh and try again.';
 else{$secret=trim((string)($_POST['secret_key']??''));$public=trim((string)($_POST['public_key']??''));$webhook=trim((string)($_POST['webhook_secret']??''));if($secret!==''&&!preg_match('/^sk_(test|live)_/',$secret))$errors[]='The Stripe secret key is not valid.';if($public!==''&&!preg_match('/^pk_(test|live)_/',$public))$errors[]='The Stripe publishable key is not valid.';if($webhook!==''&&!str_starts_with($webhook,'whsec_'))$errors[]='The webhook signing secret is not valid.';
 if(!$errors){$source=(string)file_get_contents($envPath);if($secret!=='')$source=updateEnv($source,'STRIPE_SECRET_KEY',$secret);if($public!=='')$source=updateEnv($source,'STRIPE_PUBLIC_KEY',$public);if($webhook!=='')$source=updateEnv($source,'STRIPE_WEBHOOK_SECRET',$webhook);if(file_put_contents($envPath,$source,LOCK_EX)===false)$errors[]='The .env file is not writable.';else{$saved=true;}}}
}
$configured=str_starts_with((string)Env::get('STRIPE_SECRET_KEY',''),'sk_');$webhookUrl=rtrim((string)Env::get('APP_URL',''),'/').'/stripe/webhook';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stripe setup · Veelox Digital</title><style>:root{--ink:#18202b;--muted:#697386;--line:#e4e7ed;--violet:#7357eb}*{box-sizing:border-box}body{margin:0;min-height:100vh;padding:35px;background:#f4f5f8;color:var(--ink);font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.card{width:min(100%,720px);margin:auto;padding:38px;background:#fff;border:1px solid var(--line);border-radius:22px;box-shadow:0 20px 65px rgba(22,27,40,.1)}.brand{display:flex;align-items:center;gap:11px;margin-bottom:28px}.mark{display:grid;place-items:center;width:40px;height:40px;border-radius:12px;background:var(--violet);color:#fff;font-weight:800}h1{margin:0;font-size:34px}p{color:var(--muted;);line-height:1.6}.notice{padding:13px 15px;border-radius:10px;background:#eaf9f2;color:#277253}.error{background:#fff0f0;color:#a53f3f}.field{display:block;margin-top:17px;font-size:11px;font-weight:750}.field input{display:block;width:100%;margin-top:7px;padding:12px;border:1px solid var(--line);border-radius:9px}.webhook{margin:22px 0;padding:16px;border-radius:11px;background:#f5f3ff}.webhook code{display:block;margin-top:7px;overflow:auto;color:#5543b3}button,.button{display:inline-flex;margin-top:18px;padding:12px 17px;border:0;border-radius:9px;background:var(--violet);color:#fff;text-decoration:none;font-weight:750;cursor:pointer}.button{margin-left:8px;background:#efedf8;color:#5b49b0}</style></head><body><main class="card"><div class="brand"><span class="mark">V</span><strong>Veelox Digital</strong></div><h1>Stripe setup</h1><p>Add keys from your Stripe Dashboard. Leave an existing key blank to keep it unchanged.</p><?php if($saved): ?><div class="notice">Stripe settings were saved. Sign out and back in if the payment button does not appear immediately.</div><?php endif; ?><?php if($errors): ?><div class="notice error"><?= implode('<br>',array_map('htmlspecialchars',$errors)) ?></div><?php endif; ?><div class="webhook"><strong>Stripe webhook endpoint</strong><code><?= htmlspecialchars($webhookUrl) ?></code><small>Subscribe it to checkout.session.completed, checkout.session.async_payment_succeeded, checkout.session.async_payment_failed and checkout.session.expired.</small></div><form method="post"><input type="hidden" name="_token" value="<?= htmlspecialchars(Csrf::token()) ?>"><label class="field">Publishable key<input name="public_key" autocomplete="off" placeholder="pk_test_... or pk_live_..."></label><label class="field">Secret key<input type="password" name="secret_key" autocomplete="new-password" placeholder="sk_test_... or sk_live_..."></label><label class="field">Webhook signing secret<input type="password" name="webhook_secret" autocomplete="new-password" placeholder="whsec_..."></label><button type="submit">Save Stripe settings</button><a class="button" href="/invoices">Back to invoices</a></form></main></body></html>
